   370|    }
   371|    return { branch: 'primary_realtime', label: 'primary_realtime', context: `db insert · source ${runtimeSource}${statusFragment}` };
   372|  }
   373|
   374|  if (deliveryBranch === 'local_fallback') {
   375|    return { branch: 'snapshot_fallback', label: 'snapshot_fallback', context: `local fallback path${statusFragment}` };
