   108|  const [isPrimary, setIsPrimary] = useState<boolean>(false);
   109|  const [appActive, setAppActive] = useState<boolean>(
   110|    (AppState.currentState ?? 'active') === 'active',
   111|  );
   112|  const mountedRef = useRef<boolean>(true);
   113|
   114|  // Singleton enforcement — runs once per mount.
   115|  useEffect(() => {
   116|    mountedRef.current = true;
   117|    ADV_EXEC_INSTANCE_COUNT += 1;
   118|    const primary = ADV_EXEC_INSTANCE_COUNT === 1;
   119|    setIsPrimary(primary);
   120|    if (!primary) {
   121|      console.log('[IVX_ADV_EXEC] DUPLICATE_MOUNT_SUPPRESSED', { totalInstances: ADV_EXEC_INSTANCE_COUNT });
   122|    }
   123|    return () => {
   124|      mountedRef.current = false;
   125|      ADV_EXEC_INSTANCE_COUNT = Math.max(0, ADV_EXEC_INSTANCE_COUNT - 1);
   126|    };
   127|  }, []);
   128|
   129|  // AppState-aware polling — pause when backgrounded/inactive, resume on foreground.
   130|  useEffect(() => {
   131|    const sub = AppState.addEventListener('change', (next: AppStateStatus) => {
   132|      if (!mountedRef.current) return;
   133|      setAppActive(next === 'active');
   134|    });
   135|    return () => {
   136|      sub.remove();
   137|    };
   138|  }, []);
   139|
   140|  const pollingEnabled = isPrimary && appActive;
   141|  const query = useQuery<ExecutionSnapshot | null>({
   142|    queryKey: ['ivx-senior-dev', 'execution-stream'],
   143|    queryFn: fetchSnapshot,
   144|    refetchInterval: pollingEnabled ? POLL_INTERVAL_MS : false,
   145|    refetchIntervalInBackground: false,
   146|    refetchOnWindowFocus: pollingEnabled,
   147|    refetchOnReconnect: pollingEnabled,
   148|    staleTime: POLL_STALE_MS,
   149|    enabled: isPrimary});
   150|
   151|  const onRefresh = useCallback(() => {
   152|    void query.refetch();
