   154|
   155|  const data = query.data ?? null;
   156|  const events = useMemo(() => (data?.events ?? []).slice().reverse(), [data?.events]);
   157|
   158|  // Render nothing for duplicate mounts AFTER all hooks (stable hook order).
   159|  if (!isPrimary) return null;
   160|
   161|  if (query.isLoading && !data) {
   162|    return (
   163|      <View style={styles.loading} testID="ivx-advanced-exec-loading">
   164|        <ShimmerIndicator color="#1f6feb" />
   165|        <Text style={styles.muted}>Connecting to execution stream…</Text>
