   170|  return (
   171|    <View style={styles.container} testID="ivx-advanced-exec-mode">
   172|      <View style={styles.header}>
   173|        <View style={{ flex: 1 }}>
   174|          <Text style={styles.title}>Advanced Execution Mode</Text>
   175|          <Text style={styles.muted}>{data ? `seq #${data.latestSeq} · updated ${formatTime(data.generatedAt)}` : 'No data yet'}</Text>
   176|        </View>
   177|        <Pressable onPress={onRefresh} style={styles.refreshBtn} testID="ivx-advanced-exec-refresh">
   178|          <Text style={styles.refreshLabel}>Refresh</Text>
   179|        </Pressable>
   180|      </View>
   181|
   182|      <CurrentTaskBanner task={data?.currentTask ?? null} />
