   184|      <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.tabsRow} style={styles.tabsScroll}>
   185|        {TABS.map((t) => {
   186|          const count = t.id === 'live' ? events.length
   187|            : t.id === 'files' ? (data?.counts.file_activity ?? 0)
   188|            : t.id === 'tools' ? (data?.counts.tool_call ?? 0) + (data?.counts.file_activity ?? 0) + (data?.counts.repo_activity ?? 0)
   189|            : t.id === 'patches' ? (data?.counts.patch_event ?? 0)
