   192|            : t.id === 'watchdog' ? (data?.openIncidents.length ?? 0)
   193|            : t.id === 'repo' ? (data?.counts.repo_activity ?? 0)
   194|            : (data?.counts.thinking ?? 0) + (data?.counts.reasoning ?? 0);
   195|          const isActive = activeTab === t.id;
   196|          return (
