   402|function formatTime(iso: string): string {
   403|  try {
   404|    const d = new Date(iso);
   405|    if (Number.isNaN(d.getTime())) return iso;
   406|    const hh = String(d.getHours()).padStart(2, '0');
   407|    const mm = String(d.getMinutes()).padStart(2, '0');
   408|    const ss = String(d.getSeconds()).padStart(2, '0');
   409|    return `${hh}:${mm}:${ss}`;
   410|  } catch {
   411|    return iso;
   412|  }
